fn average(v: &Vec[Float64]) -> Float64 {
  if v.len() == 0 { return 0.0; }
  var sum = 0.0;
  var i = 0;
  while i < v.len() {
    sum = sum + v[i];
    i = i + 1;
  }
  return sum / (v.len() as Float64);
}

fn normalize(v: &mut Vec[Float64]) -> Unit {
  if v.len() == 0 { return; }
  var max = v[0];
  var i = 1;
  while i < v.len() {
    if v[i] > max { max = v[i]; }
    i = i + 1;
  }
  if max == 0.0 { return; }
  i = 0;
  while i < v.len() {
    v[i] = v[i] / max;
    i = i + 1;
  }
}

fn main() -> Int {
  var v = Vec[Float64]();
  v.push(2.0); v.push(4.0); v.push(6.0);
  let avg = average(&v);
  return (avg * 10.0) as Int;
}
